    2: [['p117', 'c220', 'p150'], ['p41', B('Canticle · Sirach 36', 'Sirach 36:1-5', 'Sirach 36:10-13'), 'p18(2-7)'], ['p42', B('Canticle · Isaiah 38', 'Isaiah 38:10-14', 'Isaiah 38:17-20'), 'p64'], ['p76', B('Canticle · 1 Samuel 2', '1 Samuel 2:1-10'), 'p96'], ['p79', B('Canticle · Isaiah 12', 'Isaiah 12:1-6'), 'p80'], ['p50', B('Canticle · Habakkuk 3', 'Habakkuk 3:2-4', 'Habakkuk 3:13', 'Habakkuk 3:15-19'), 'p147'], ['p91', B('Canticle · Deuteronomy 32', 'Deuteronomy 32:1-12'), 'p8']],
