      const first = which === 'V' && dow === 6;
      const k = dd(date, adv);
      if (first) { if (k < -1 || k > 20) return null; } else if (k < 0 || !(m === 11 || (m === 12 && dm <= 23))) return null;
      const wk = first ? Math.floor((k + 1) / 7) + 1 : Math.floor(k / 7) + 1;   // for first Vespers: the coming Sunday's number
      if (wk < 1 || wk > 4) return null;
      const sunday = dow === 0 && !first, ferial = !sunday && !first;
      const great = m === 12 && dm >= 16 && dm <= 23 && which === 'V' ? ADV.great[dm] : null;
      const ember = wk === 3 && [3, 5, 6].includes(dow) && !first;
      const r = Sar && Sar.sarum ? Sar.sarum(date) : null;
      const plain = !r || ['Weekday', 'Sunday', 'Ember Day', 'Vigil', 'Memory only', 'Saint of the Missal'].includes(r.rank) || first || r.rank === 'Three lessons';
      const name = first ? `First Vespers of the ${ORD4(wk)} Sunday in Advent` : sunday ? `${ORD4(wk)} Sunday in Advent` : `${['', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'][dow]} in the ${ORD4(wk).toLowerCase()} week of Advent${ember ? ' (Ember Day)' : ''}`;
      let h = `<p class="muted" style="font-size:.82rem">${esc(name)}. Sarum ${which === 'L' ? 'Lauds' : 'Vespers'} for Advent · antiphons, chapters, hymns, responds and memorials from the Hayes <i>Breviary Offices</i> (1880), Proper of Seasons · psalms in the Douay version · the Sarum collect (Hayes gives the Prayer Book collect first, then the Sarum one in brackets; this is the Sarum one).</p>`;
      if (!plain) h += `<p class="muted" style="font-size:.82rem">Today is <b>${esc(r.title)}</b> (${esc(r.rank)}). Its own Office from the Proper or Common of Saints is not in the app yet, so this is the Advent office of the day.</p>`;
      h += sec('Opening', lines((which === 'L' ? 'V. Send, O Lord, the Lamb, the Ruler of the land.\nR. From the rock of the wilderness, unto the mount of the daughter of Sion.\n' : '') + OPEN.replace('\nAlleluia.', '\nAlleluia.')));
      let groups;
      if (which === 'L') {
        const base = LAUDS[dow];
        if (sunday) groups = base.map((g, i) => [incipit(ADV.sun[wk][0][i]), ADV.sun[wk][0][i], g[2]]);
        else if (wk >= 3 && ADV.ferAnts[dow]) groups = base.map((g, i) => [incipit(ADV.ferAnts[dow][i]), ADV.ferAnts[dow][i], g[2]]);
        else groups = base;
      } else groups = VESP[dow];
      h += sec('Psalms', '<p class="muted" style="font-size:.78rem;margin:2px 0 6px">Only the first words of the antiphon before the psalm, the whole antiphon after it.' + (which === 'L' && ferial && wk < 3 ? ' In the first two weeks of Advent the weekday psalm antiphons are those of the Psalter.' : '') + (which === 'V' ? ' Vespers psalms and antiphons are those of the Psalter.' : '') + '</p>' + groups.map(group).join(''));
      let cap;
      if (which === 'L') cap = sunday ? ADV.sun[wk][1] : ['Jeremiah 23', 'Behold, the days come, saith the Lord, that I will raise unto David a righteous branch, and a King shall reign and prosper, and shall execute judgment and justice in the earth.'];
      else if (first) cap = ADV.fv[wk];
      else cap = sunday ? (wk === 3 ? ['1 Corinthians 4', ADV.sun[3][1][1]] : ADV.sun[wk][1]) : ['Jeremiah 23', 'In His days Judah shall be saved, and Israel shall dwell safely: and this is His Name whereby He shall be called, The Lord our Righteousness.'];
      h += sec(`Chapter · ${cap[0]}`, lines(cap[1] + '\nR. Thanks be to God.'));
      if (which === 'V') h += sec('Respond', lines(first ? ADV.fv[wk][2] : (m === 12 && dm >= 16) || (sunday && wk === 3 && m === 12 && dm >= 16) ? MAKEHASTE : ARISE));
      h += sec(which === 'L' ? 'Hymn · Vox clara ecce intonat' : 'Hymn · Conditor alme siderum', lines(which === 'L' ? VOXCLARA : CONDITOR));
      h += sec('Versicle', lines(which === 'L' ? 'V. A voice crying in the wilderness.\nR. Prepare ye the way of the Lord: make straight a highway for our God.' : 'V. Drop down, ye heavens, from above.\nR. And let the skies pour down righteousness: let the earth open, and let them bring forth salvation.'));
      let ca = '', caLabel = '';
      if (which === 'L') ca = sunday ? ADV.sun[wk][2] : (ADV.ben[wk] || {})[dow] || '';
      else if (great) { ca = great[1]; caLabel = ` · the great antiphon ${great[0]}`; }
      else if (first) ca = ADV.fv[wk][3];
      else ca = sunday ? ADV.sun[wk][3] : (ADV.mag[wk] || {})[dow] || '';
      const cant = which === 'L' ? '231' : '232';
      h += sec((which === 'L' ? 'Benedictus' : 'Magnificat') + caLabel, (ca ? ant(great ? ca : incipit(ca), !great) : '') + canticle(cant) + (ca ? ant(ca) : ''));
      const vespPrecesOff = which === 'V' && m === 12 && dm >= 16, laudsEmber = which === 'L' && ember;
      if (ferial && !vespPrecesOff && !laudsEmber) h += sec('Petitions', lines(PRECES_A) + `<div class="muted" style="font-size:.78rem;margin-top:6px">Psalm 50 (Miserere)${which === 'V' ? ' and Psalm 129 (De profundis)' : ''}:</div>` + body('50') + (which === 'V' ? body('129') : '') + glo() + lines(PRECES_B));
      else h += sec('', lines('V. The Lord be with you.\nR. And with thy spirit.'));
      const coll = which === 'L' && ember && ADV.emberColl[dow] ? ADV.emberColl[dow] : ADV.coll[wk];
      h += sec(`Collect · ${which === 'L' && ember && ADV.emberColl[dow] ? 'of the Ember Day' : ORD4(wk) + ' Sunday in Advent'}`, lines('Let us pray.') + lines(coll) + '<br>' + lines(ENDV));
      // memorials: Sundays and first Vespers only S. Mary; ferias S. Mary and All Saints (All Saints left out on 16 December)
      let maryAnt;
      if (first) maryAnt = 'Hail, Mary, full of grace, the Lord is with thee: blessed art thou among women. Alleluia.';
      else if (sunday) maryAnt = which === 'L' ? 'The Angel Gabriel was sent to Mary: a virgin espoused to Joseph.' : (/^Blessed art thou, Mary/.test(ca) ? 'Fear not, Mary; thou hast found favour with God: behold, thou shalt conceive and bring forth a Son. Alleluia.' : 'Blessed art thou, Mary, that hast believed: for there shall be a performance of those things which were told thee from the Lord. Alleluia.');
      else maryAnt = which === 'L' ? 'The Holy Ghost shall come down upon thee, Mary, fear not: who hast in thy womb the Son of God. Alleluia.' : 'Fear not, Mary; thou hast found favour with God: behold, thou shalt conceive and bring forth a Son. Alleluia.';
      let mem = sec('Memorial of S. Mary', ant(maryAnt) + lines(MARY_V) + lines('Let us pray.') + lines(MARY_C));
      if (ferial && !(m === 12 && dm === 16)) { const [t, a, v, c] = SAINTS_ADV; mem += sec(t, ant(a) + lines(v) + lines('Let us pray.') + lines(c)); }
      h += '<p class="muted" style="font-size:.78rem;margin:8px 0 2px">Memorials in Advent:</p>' + mem + sec('', lines(ENDV));
      if (which === 'L') h += sec('For the Peace of the Church', body('122') + glo() + lines("Lord, have mercy. Christ, have mercy. Lord, have mercy.\nOur Father (said silently to the end; then aloud):\nV. And lead us not into temptation.\nR. But deliver us from evil.\n" + PRECES_B) + lines('Let us pray.') + lines(PEACE_C));
